INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 100101, 27, "ヒヨリ", 2, 155, 44, "人助けが大好き！　前向き格闘娘", 8, 0, "人助け、応援", "東山奈央", 16, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 100201, 5, "ユイ", 2, 158, 47, "戦闘のサポートが得意な、心優しい少女", 4, 0, "料理、人間観察", "種田梨沙", 17, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 100301, 12, "レイ", 2, 163, 46, "クールで何事にも真っ直ぐな剣士", 1, 0, "読書、乗馬、お茶", "早見沙織", 18, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 100401, 10, "ミソギ", 5, 128, 27, "探検好きのイタズラっ子", 8, 0, "いたずら、探検", "諸星すみれ", 9, "リトルリリカル", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 100501, 25, "マツリ", 8, 146, 40, "ヒーローに憧れる騎士見習いの少女", 11, 0, "ヒーローごっこ", "下田麻美", 12, "王宮騎士団（NIGHTMARE）", "？？？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 100601, 22, "アカリ", 7, 150, 42, "甘え上手なみんなの人気者", 11, 0, "サックス", "浅倉杏美", 13, "悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 100701, 23, "ミヤコ", 7, 130, 32, "プリン大好きゴースト娘", 1, 0, "プリンを食べること", "雨宮天", 14, "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "AB", 100801, 10, "ユキ", 15, 150, 40, "ボクは誰よりも美しい", 10, 0, "鏡で自分を見ること", "大空直美", 14, "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 100901, 5, "アンナ", 13, 159, 45, "前世を信じる中二病患者、「疾風の冥姫」", 7, 0, "小説執筆", "髙野麻美", 17, "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 101001, 22, "マホ", 10, 155, 42, "マホマホ王国のプリンセス", 9, 0, "空想、ぬいぐるみ集め", "内田真礼", 16, "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 101101, 25, "リノ", 3, 156, 44, "人懐っこくてマシンガントークな妹系少女", 8, 0, "お裁縫", "阿澄佳奈", 15, "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 101201, 24, "ハツネ", 6, 156, 46, "みんなのために超能力を使う眠り姫", 12, 0, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香", 17, "フォレスティエ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 101301, 21, "ナナカ", 13, 166, 55, "オタク全開な魔法少女", 8, 0, "読書、魔法", "佳村はるか", 18, "トワイライトキャラバン", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 101401, 3, "カスミ", 10, 152, 41, "頭脳明晰な美少女名探偵", 11, 0, "読書、推理", "水瀬いのり", 15, "自警団（カォン）", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "O", 101501, 5, "ミサト", 6, 165, 54, "母性溢れる優しいみんなの「ミサト先生」", 9, 0, "絵本作り", "國府田マリ子", 21, "フォレスティエ", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 101601, 10, "スズナ", 14, 167, 48, "天真爛漫で人気者のカリスマモデル", 4, 0, "ファッション", "上坂すみれ", 17, "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 101701, 7, "カオリ", 10, 158, 53, "いつでも「なんくるないさ～」な天然娘", 7, 0, "踊り、空手", "高森奈津美", 17, "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 101801, 14, "イオ", 14, 162, 52, "多くの男性を魅了する無垢な女教師", 8, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", 23, "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 102001, 3, "ミミ", 5, 117, 21, "お歌もにんじんも、ウサギさんも大好き♪", 4, 0, "かわいいもの集め", "日高里菜", 10, "リトルリリカル", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 102101, 9, "クルミ", 9, 150, 40, "泣き虫で臆病な守ってあげたい女の子", 6, 0, "観劇、おままごと", "植田佳奈", 12, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 102201, 22, "ヨリ", 7, 150, 40, "人見知りであまのじゃくな女の子", 11, 0, "ゲーム全般", "原紗友里", 13, "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 102301, 10, "アヤネ", 9, 148, 38, "ぷうきちといつも一緒！", 5, 0, "屋内でできる遊び", "芹澤優", 14, "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 102501, 12, "スズメ", 9, 154, 43, "お嬢さまのためにがんばるドジっ娘メイド", 12, 0, "ご奉仕", "悠木碧", 15, "サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "B", 102601, 1, "リン", 11, 144, 42, "遊びと睡眠が何より大事なぐうたら娘", 1, 0, "あんパン", "小岩井ことり", 17, "牧場（エリザベスパーク）", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 102701, 30, "エリコ", 13, 154, 43, "運命の相手に一途すぎる乙女", 7, 0, "実験、裁縫、料理", "橋本ちなみ", 16, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 102801, 4, "サレン", 9, 156, 43, "救護院を経営する優しい庶民派お嬢様", 10, 0, "経営、お茶会", "堀江由衣", 17, "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 102901, 24, "ノゾミ", 4, 157, 40, "歌って踊れる大人気アイドル", 1, 0, "舞台鑑賞、ダンス", "日笠陽子", 17, "カルミナ", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 103001, 31, "ニノン", 15, 163, 51, "トーゴクの神秘、オシエテクダサイ！", 8, 0, "忍法開発", "佐藤聡美", 16, "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "AB", 103101, 22, "シノブ", 7, 157, 42, "占いが得意な霊能少女", 12, 0, "占い", "大坪由佳", 18, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 103201, 12, "アキノ", 12, 157, 45, "一人前の商人を目指すパワフルお嬢様", 3, 0, "慈善事業", "松嵜麗", 18, "メルクリウス財団", "この私とともにいる限り、\nお金に不自由はさせませんわ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 103301, 3, "マヒル", 11, 142, 35, "みんなを笑顔にするお笑い牧場主", 3, 0, "漫才", "新田恵海", 20, "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 103401, 16, "ユカリ", 12, 164, 55, "純情でほっとけない大人の女性", 3, 0, "ウインドーショッピング", "今井麻美", 22, "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 103601, 2, "キョウカ", 5, 118, 21, "礼儀正しくしっかり者のちびっ子優等生", 2, 0, "お勉強", "小倉唯", 8, "リトルリリカル", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 103701, 11, "トモ", 8, 149, 43, "義理堅くてからかい好きな剣術少女", 8, 0, "剣術、年長者をからかう", "茅原実里", 13, "王宮騎士団（NIGHTMARE）", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 103801, 3, "シオリ", 11, 153, 40, "読書が趣味の病弱少女", 11, 0, "読書、お散歩", "小清水亜美", 14, "牧場（エリザベスパーク）", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "AB", 104001, 6, "アオイ", 6, 158, 44, "「友達」に憧れる、エルフの森の女の子", 6, 0, "友達作りのイメトレ", "花澤香菜", 13, "フォレスティエ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 104201, 3, "チカ", 4, 163, 46, "人々を守るために歌う、唱喚士の少女", 6, 0, "各種楽器", "福原綾香", 17, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 104301, 9, "マコト", 10, 168, 54, "男勝りで情に厚いワイルド娘", 8, 0, "お菓子作り", "小松未可子", 17, "自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 104401, 5, "イリヤ", 7, 172, 50, "かつては夜を支配した最強の吸血鬼", 5, 0, "世界征服", "丹下桜", "??", "悪魔偽王国軍（ディアボロス）", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 104501, 19, "クウカ", 15, 157, 49, "妄想大好き！　ほんとは照れ屋な女の子", 11, 0, "小説を読むこと", "長妻樹里", 18, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 104601, 1, "タマキ", 12, 158, 48, "弱きを助け強きをくじく猫娘", 3, 0, "猫とたわむれること", "沼倉愛美", 19, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 104701, 25, "ジュン", 8, 171, 50, "素顔を見せない冷静沈着な女性騎士", 10, 0, "格闘技、湯浴み", "川澄綾子", 25, "王宮騎士団（NIGHTMARE）", "？？？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 104801, 11, "ミフユ", 12, 163, 49, "仕事も私事も効率優先な傭兵少女", 11, 0, "傭兵などのアルバイト", "田所あずさ", 20, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 104901, 24, "シズル", 3, 168, 54, "お姉ちゃんがお世話してあげるからねっ！", 10, 0, "家事全般", "生天目仁美", 18, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 105001, 3, "ミサキ", 14, 120, 22, "ちょっとおませな恋に恋する女の子", 1, 0, "ファッション誌鑑賞、コスメ集め", "久野美咲", 11, "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 105101, 7, "ミツキ", 13, 166, 53, "実験が趣味の危険な科学者", 3, 0, "研究、実験", "三石琴乃", 27, "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 105201, 14, "リマ", 11, 150, 100, "乙女チックなもふもふアニマル", 3, 0, "毛繕い、お喋り", "徳井青空", 17, "牧場（エリザベスパーク）", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 105301, 28, "モニカ", 15, 140, 33, "見た目も中身もお子ちゃまな異国の軍人", 7, 0, "お菓子屋通い", "辻あゆみ", 17, "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 105401, 7, "ツムギ", 4, 153, 45, "ファッション大好きなキュートガール", 9, 0, "裁縫", "木戸衣吹", 14, "カルミナ", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "O", 105501, 7, "アユミ", 15, 155, 43, "どこまでも一途に慕う、純情乙女", 4, 0, "観察", "大関英里", 16, "ヴァイスフリューゲル　ランドソル支部", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 105601, 11, "ルカ", 13, 167, 54, "人情味溢れる粋でいなせな「姉御」", 7, 0, "釣り", "佐藤利奈", 25, "トワイライトキャラバン", "test");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 105701, 10, "ジータ", "", 156, 45, "空への冒険を夢見る騎空士の少女", 3, 0, "冒険、おしゃべり", "金元寿子", 17, "？？？", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 105801, 31, "ペコリーヌ", 1, 156, 46, "いつも元気な腹ペコ少女", 3, 0, "食べ歩き、料理", "M・A・O", 17, "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "B", 105901, 11, "コッコロ", 1, 140, 35, "主を慕う、小さなガイド役", 5, 0, "瞑想、動植物の飼育", "伊藤美来", 11, "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 106001, 2, "キャル", 1, 152, 39, "行き倒れの謎のネコミミ魔法使い", 9, 0, "猫と遊ぶ", "立花理香", 14, "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 106101, 11, "ムイミ", "", 148, 40, "さまよえる謎の少女", 8, 0, "冒険、思い出話", "潘めぐみ", 16, "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "O", 106301, 17, "アリサ", "", 155, 42, "森番を目指すエルフの少女", 6, 0, "キレイな葉っぱを集めること", "優木かな", 15, "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ドラゴン族", "B", 106401, 14, "シェフィ", 1, 147, "???", "記憶喪失のドラゴン娘", 12, 0, "読書、ストレッチ", "近藤玲奈", 14, "美食殿", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ドラゴン族", "B", 106501, 25, "カヤ", 17, 156, "???", "拳で語る喧嘩屋ドラゴン少女", 6, 0, "格闘技", "小市眞琴", 16, "ドラゴンズネスト", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ドラゴン族", "AB", 106601, 29, "イノリ", 17, 145, "???", "口が達者なヘタレドラゴン", 9, 0, "ゲーム", "藤田茜", 13, "ドラゴンズネスト", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ドラゴン族", "O", 106701, 17, "ホマレ", 17, 168, "???", "妖しい微笑で全てを見透かす臥竜の頭領", 4, 0, "絵画、読書", "大西沙織", 25, "ドラゴンズネスト", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 106801, 25, "ラビリスタ", 3, 160, "??", "秘密結社ラビリンスの『迷宮女王』", 7, 0, "人間観察", "沢城みゆき", 25, "ラビリンス", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 106901, 1, "カイザーインサイト", "", 166, "??", "謎に包まれたランドソルの主", 7, 0, "占い、支配", "蒼井翔太", 29, "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "O", 107001, 24, "ネネカ", "", 149, "??", "研究所に隠れ住む物静かなお姉さん", 3, 0, "物真似、芸術鑑賞", "井口裕香", 24, "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 107101, 7, "クリスティーナ", 8, 165, "??", "傍若無人な王宮騎士団副団長", 2, 0, "強敵との闘争", "たかはし智秋", 27, "王宮騎士団（NIGHTMARE）", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 107501, 31, "ペコリーヌ（サマー）", 1, 156, 46, "いつも元気な腹ペコ少女", 3, 0, "食べ歩き、料理", "M・A・O", 17, "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "B", 107601, 11, "コッコロ（サマー）", 1, 140, 35, "主を慕う、小さなガイド役", 5, 0, "瞑想、動植物の飼育", "伊藤美来", 11, "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 107701, 12, "スズメ（サマー）", 9, 154, 43, "お嬢さまのためにがんばるドジっ娘メイド", 12, 0, "ご奉仕", "悠木碧", 15, "サレンディア救護院", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 107801, 2, "キャル（サマー）", 1, 152, 39, "行き倒れの謎のネコミミ魔法使い", 9, 0, "猫と遊ぶ", "立花理香", 14, "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 107901, 1, "タマキ（サマー）", 12, 158, 48, "弱きを助け強きをくじく猫娘", 3, 0, "猫とたわむれること", "沼倉愛美", 19, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 108001, 11, "ミフユ（サマー）", 12, 163, 49, "仕事も私事も効率優先な傭兵少女", 11, 0, "傭兵などのアルバイト", "田所あずさ", 20, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "AB", 108101, 22, "シノブ（ハロウィン）", 7, 157, 42, "占いが得意な霊能少女", 12, 0, "占い", "大坪由佳", 18, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 108201, 23, "ミヤコ（ハロウィン）", 7, 130, 32, "プリン大好きゴースト娘", 1, 0, "プリンを食べること", "雨宮天", 14, "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 108301, 3, "ミサキ（ハロウィン）", 14, 120, 22, "ちょっとおませな恋に恋する女の子", 1, 0, "ファッション誌鑑賞、コスメ集め", "久野美咲", 11, "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 108401, 3, "チカ（クリスマス）", 4, 163, 46, "人々を守るために歌う、唱喚士の少女", 6, 0, "各種楽器", "福原綾香", 17, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 108501, 9, "クルミ（クリスマス）", 9, 150, 40, "泣き虫で臆病な守ってあげたい女の子", 6, 0, "観劇、おままごと", "植田佳奈", 12, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 108601, 10, "アヤネ（クリスマス）", 9, 148, 38, "ぷうきちといつも一緒！", 5, 0, "屋内でできる遊び", "芹澤優", 14, "サレンディア救護院", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 108701, 27, "ヒヨリ（ニューイヤー）", 2, 155, 44, "人助けが大好き！　前向き格闘娘", 8, 0, "人助け、応援", "東山奈央", 16, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 108801, 5, "ユイ（ニューイヤー）", 2, 158, 47, "戦闘のサポートが得意な、心優しい少女", 4, 0, "料理、人間観察", "種田梨沙", 17, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 108901, 12, "レイ（ニューイヤー）", 2, 163, 46, "クールで何事にも真っ直ぐな剣士", 1, 0, "読書、乗馬、お茶", "早見沙織", 18, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 109001, 30, "エリコ（バレンタイン）", 13, 154, 43, "運命の相手に一途すぎる乙女", 7, 0, "実験、裁縫、料理", "橋本ちなみ", 16, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 109101, 24, "シズル（バレンタイン）", 3, 168, 54, "お姉ちゃんがお世話してあげるからねっ！", 10, 0, "家事全般", "生天目仁美", 18, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 109201, 1, "アン", "", 156, 55, "英霊と契約を結んだマナリアの天才王女", 12, 0, "読書", "日笠陽子", 17, "？？？", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 109301, 4, "ルゥ", "", 144, 45, "マナリア魔法学院の新入生", 2, 0, "食べること、眠ること", "こやまきみこ", 16, "？？？", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("半人半竜", "B", 109401, 3, "グレア", "", 167, 67, "人を超越した力を有す心優しい竜姫", 11, 0, "ピアノ", "福原綾香", 17, "？？？", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 109501, 19, "クウカ（オーエド）", 15, 157, 49, "妄想大好き！　ほんとは照れ屋な女の子", 11, 0, "小説を読むこと", "長妻樹里", 18, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 109601, 31, "ニノン（オーエド）", 15, 163, 51, "トーゴクの神秘、オシエテクダサイ！", 8, 0, "忍法開発", "佐藤聡美", 16, "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("鬼族", "?", 109701, 2, "レム", "", 154, "??", "鬼がかりの万能妹メイド", 2, 0, "演劇鑑賞、詩文", "水瀬いのり", 17, "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("鬼族", "?", 109801, 2, "ラム", "", 154, "??", "毒舌系鬼姉メイド", 2, 0, "読書", "村川梨衣", 17, "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ハーフエルフ", "?", 109901, 23, "エミリア", "", 164, "??", "銀髪のおっとりハーフエルフ", 9, 0, "パックの毛繕い、勉強", "高橋李依", "??", "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 110001, 10, "スズナ（サマー）", 14, 167, 48, "天真爛漫で人気者のカリスマモデル", 4, 0, "ファッション", "上坂すみれ", 17, "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 110101, 14, "イオ（サマー）", 14, 162, 52, "多くの男性を魅了する無垢な女教師", 8, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", 23, "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
