INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 112801, 3, "マヒル（レンジャー）", 11, 142, 35, "みんなを笑顔にするお笑い牧場主", 3, 0, "漫才", "新田恵海", 20, "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
