INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 113201, 5, "アンナ（サマー）", 13, 159, 45, "前世を信じる中二病患者、「疾風の冥姫」", 7, 0, "小説執筆", "髙野麻美", 17, "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 113301, 21, "ナナカ（サマー）", 13, 166, 55, "オタク全開な魔法少女", 8, 0, "読書、魔法", "佳村はるか", 18, "トワイライトキャラバン", "");
