INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 113701, 22, "アカリ（エンジェル）", 7, 150, 42, "甘え上手なみんなの人気者", 11, 0, "サックス", "浅倉杏美", 13, "悪魔偽王国軍（ディアボロス）", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 113801, 22, "ヨリ（エンジェル）", 7, 150, 40, "人見知りであまのじゃくな女の子", 11, 0, "ゲーム全般", "原紗友里", 13, "悪魔偽王国軍（ディアボロス）", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 113901, 7, "ツムギ（ハロウィン）", 4, 153, 45, "ファッション大好きなキュートガール", 9, 0, "裁縫", "木戸衣吹", 14, "カルミナ", "");
