INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 114101, 25, "マツリ（ハロウィン）", 8, 146, 40, "ヒーローに憧れる騎士見習いの少女", 11, 0, "ヒーローごっこ", "下田麻美", 12, "王宮騎士団（NIGHTMARE）", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 114201, 28, "モニカ（マジカル）", 15, 140, 33, "見た目も中身もお子ちゃまな異国の軍人", 7, 0, "お菓子屋通い", "辻あゆみ", 17, "ヴァイスフリューゲル　ランドソル支部", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 114301, 11, "トモ（マジカル）", 8, 149, 43, "義理堅くてからかい好きな剣術少女", 8, 0, "剣術、年長者をからかう", "茅原実里", 13, "王宮騎士団（NIGHTMARE）", "");
