INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 114501, 4, "サレン（クリスマス）", 9, 156, 43, "救護院を経営する優しい庶民派お嬢様", 10, 0, "経営、お茶会", "堀江由衣", 17, "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 114601, 16, "ユカリ（クリスマス）", 12, 164, 55, "純情でほっとけない大人の女性", 3, 0, "ウインドーショッピング", "今井麻美", 22, "メルクリウス財団", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 114701, 11, "ムイミ（ニューイヤー）", "", 148, 40, "さまよえる謎の少女", 8, 0, "冒険、思い出話", "潘めぐみ", 16, "？？？", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ");
