INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "B", 115501, 11, "コッコロ（儀装束）", 1, 140, 35, "主を慕う、小さなガイド役", 5, 0, "瞑想、動植物の飼育", "伊藤美来", 11, "美食殿", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 115601, 5, "ユイ（儀装束）", 2, 158, 47, "戦闘のサポートが得意な、心優しい少女", 4, 0, "料理、人間観察", "種田梨沙", 17, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 115701, 3, "カスミ（サマー）", 10, 152, 41, "頭脳明晰な美少女名探偵", 11, 0, "読書、推理", "水瀬いのり", 15, "自警団（カォン）", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 115801, 14, "リマ（シンデレラ）", 11, 150, 100, "乙女チックなもふもふアニマル", 3, 0, "毛繕い、お喋り", "徳井青空", 17, "牧場（エリザベスパーク）", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 115901, 9, "マコト（シンデレラ）", 10, 168, 54, "男勝りで情に厚いワイルド娘", 8, 0, "お菓子作り", "小松未可子", 17, "自警団（カォン）", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "O", 116001, 22, "マホ（シンデレラ）", 10, 155, 42, "マホマホ王国のプリンセス", 9, 0, "空想、ぬいぐるみ集め", "内田真礼", 16, "自警団（カォン）", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "O", 116201, 7, "クロエ（聖学祭）", 16, 154, 42, "ダウンタウン育ちのダウナー系エルフ", 8, 0, "ダーツ", "種﨑敦美", 17, "聖テレサ女学院（なかよし部）", "");
