INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "AB", 116701, 6, "アオイ（作業服）", 6, 158, 44, "「友達」に憧れる、エルフの森の女の子", 6, 0, "友達作りのイメトレ", "花澤香菜", 13, "フォレスティエ", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "AB", 116801, 1, "タマキ（作業服）", 12, 158, 48, "弱きを助け強きをくじく猫娘", 3, 0, "猫とたわむれること", "沼倉愛美", 19, "メルクリウス財団", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 116901, 11, "ミフユ（作業服）", 12, 163, 49, "仕事も私事も効率優先な傭兵少女", 11, 0, "傭兵などのアルバイト", "田所あずさ", 20, "メルクリウス財団", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 117001, 30, "エリコ（サマー）", 13, 154, 43, "運命の相手に一途すぎる乙女", 7, 0, "実験、裁縫、料理", "橋本ちなみ", 16, "トワイライトキャラバン", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 117101, 24, "シズル（サマー）", 3, 168, 54, "お姉ちゃんがお世話してあげるからねっ！", 10, 0, "家事全般", "生天目仁美", 18, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 117201, 24, "ノゾミ（サマー）", 4, 157, 40, "歌って踊れる大人気アイドル", 1, 0, "舞台鑑賞、ダンス", "日笠陽子", 17, "カルミナ", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 117301, 3, "チカ（サマー）", 4, 163, 46, "人々を守るために歌う、唱喚士の少女", 6, 0, "各種楽器", "福原綾香", 17, "カルミナ", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 117401, 7, "ツムギ（サマー）", 4, 153, 45, "ファッション大好きなキュートガール", 9, 0, "裁縫", "木戸衣吹", 14, "カルミナ", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 117501, 7, "ミツキ（オーエド）", 13, 166, 53, "実験が趣味の危険な科学者", 3, 0, "研究、実験", "三石琴乃", 27, "トワイライトキャラバン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "AB", 117601, 10, "ユキ（オーエド）", 15, 150, 40, "ボクは誰よりも美しい", 10, 0, "鏡で自分を見ること", "大空直美", 14, "ヴァイスフリューゲル　ランドソル支部", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 117701, 7, "カオリ（ハロウィン）", 10, 158, 53, "いつでも「なんくるないさ～」な天然娘", 7, 0, "踊り、空手", "高森奈津美", 17, "自警団（カォン）", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 117801, 31, "ニノン（ハロウィン）", 15, 163, 51, "トーゴクの神秘、オシエテクダサイ！", 8, 0, "忍法開発", "佐藤聡美", 16, "ヴァイスフリューゲル　ランドソル支部", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 117901, 10, "スズナ（ハロウィン）", 14, 167, 48, "天真爛漫で人気者のカリスマモデル", 4, 0, "ファッション", "上坂すみれ", 17, "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 118001, 19, "クレジッタ", 18, 160, 57, "忠義に目覚めた女商人", 9, 0, "お金を数えること、悪だくみ", "Lynn", 26, "リッチモンド商工会", "");
