INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("？？？", "?", 118601, "?", "ネビア", "", "???", "???", "幻霧に戯れる悪戯好きなガイド妖精", "?", 0, "悪戯をすること", "相坂優歌", "??", "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 119001, 14, "イオ（ノワール）", 14, 162, 52, "多くの男性を魅了する無垢な女教師", 8, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", 23, "ルーセント学院", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 119101, 19, "クウカ（ノワール）", 15, 157, 49, "妄想大好き！　ほんとは照れ屋な女の子", 11, 0, "小説を読むこと", "長妻樹里", 18, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 119201, 3, "マヒル（クリスマス）", 11, 142, 35, "みんなを笑顔にするお笑い牧場主", 3, 0, "漫才", "新田恵海", 20, "牧場（エリザベスパーク）", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "A", 119301, 25, "リノ（クリスマス）", 3, 156, 44, "人懐っこくてマシンガントークな妹系少女", 8, 0, "お裁縫", "阿澄佳奈", 15, "ラビリンス", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 119901, 23, "ミヤコ（クリスマス）", 7, 130, 32, "プリン大好きゴースト娘", 1, 0, "プリンを食べること", "雨宮天", 14, "悪魔偽王国軍（ディアボロス）", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 120001, 24, "シズル（ノワール）", 3, 168, 54, "お姉ちゃんがお世話してあげるからねっ！", 10, 0, "家事全般", "生天目仁美", 18, "ラビリンス", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
