INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 121201, 25, "ラビリスタ（オーバーロード）", 3, 160, "??", "秘密結社ラビリンスの『迷宮女王』", 7, 0, "人間観察", "沢城みゆき", 25, "ラビリンス", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "B", 121301, 9, "クルミ（ステージ）", 9, 150, 40, "泣き虫で臆病な守ってあげたい女の子", 6, 0, "観劇、おままごと", "植田佳奈", 12, "サレンディア救護院", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 121401, 3, "ミサキ（ステージ）", 14, 120, 22, "ちょっとおませな恋に恋する女の子", 1, 0, "ファッション誌鑑賞、コスメ集め", "久野美咲", 11, "ルーセント学院", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
