INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "A", 121901, 5, "アンナ（パイレーツ）", 13, 159, 45, "前世を信じる中二病患者、「疾風の冥姫」", 7, 0, "小説執筆", "髙野麻美", 17, "トワイライトキャラバン", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "AB", 122001, 22, "シノブ（パイレーツ）", 7, 157, 42, "占いが得意な霊能少女", 12, 0, "占い", "大坪由佳", 18, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "AB", 122101, 6, "アオイ（キャンプ）", 6, 158, 44, "「友達」に憧れる、エルフの森の女の子", 6, 0, "友達作りのイメトレ", "花澤香菜", 13, "フォレスティエ", "");
