INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "AB", 122301, 6, "ヴァンピィ", "", 149, 41, "けんぞくのご主人様", 12, 0, "お散歩、お料理", "釘宮理恵", "??", "？？？", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 122401, 27, "ヒヨリ（サマー）", 2, 155, 44, "人助けが大好き！　前向き格闘娘", 8, 0, "人助け、応援", "東山奈央", 16, "トゥインクルウィッシュ", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "B", 122501, 12, "レイ（サマー）", 2, 163, 46, "クールで何事にも真っ直ぐな剣士", 1, 0, "読書、乗馬、お茶", "早見沙織", 18, "トゥインクルウィッシュ", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 122601, 5, "ユイ（サマー）", 2, 158, 47, "戦闘のサポートが得意な、心優しい少女", 4, 0, "料理、人間観察", "種田梨沙", 17, "トゥインクルウィッシュ", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 122701, 2, "キョウカ（サマー）", 5, 118, 21, "礼儀正しくしっかり者のちびっ子優等生", 2, 0, "お勉強", "小倉唯", 8, "リトルリリカル", "");
