INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 126901, 28, "ランファ（サマー）", 19, 165, 53, "静寂を求め歌う陰気少女", 12, 0, "歌、読書、詩を書くこと", "原田彩楓", 20, "レイジ・レギオン", "");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "AB", 127001, 19, "クウカ（サマー）", 15, 157, 49, "妄想大好き！　ほんとは照れ屋な女の子", 11, 0, "小説を読むこと", "長妻樹里", 18, "ヴァイスフリューゲル　ランドソル支部", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "AB", 127101, 22, "シノブ（サマー）", 7, 157, 42, "占いが得意な霊能少女", 12, 0, "占い", "大坪由佳", 18, "悪魔偽王国軍（ディアボロス）", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("獣人族", "A", 127201, 2, "キャル（編入生）", 1, 152, 39, "行き倒れの謎のネコミミ魔法使い", 9, 0, "猫と遊ぶ", "立花理香", 14, "美食殿", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("魔族", "O", 127301, 10, "スズナ（編入生）", 14, 167, 48, "天真爛漫で人気者のカリスマモデル", 4, 0, "ファッション", "上坂すみれ", 17, "ルーセント学院", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("エルフ", "A", 127501, 4, "サレン（サラサリア）", 9, 156, 43, "救護院を経営する優しい庶民派お嬢様", 10, 0, "経営、お茶会", "堀江由衣", 17, "サレンディア救護院", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
