INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ヒューマン", "O", 127901, 31, "ペコリーヌ（クリスマス）", 1, 156, 46, "いつも元気な腹ペコ少女", 3, 0, "食べ歩き、料理", "M・A・O", 17, "美食殿", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
